/// One font: what it can draw, and the measurements a line needs to be laid out.
///
/// **Owned rather than a pair of function pointers**, because a font can now come from a file - `fonts/<name>.json`,
/// beside the applets - and a file's glyphs live on the heap. The built-in font is built once into the same shape, so
/// there is one kind of font and not two.
///
/// The metrics live *with* the font rather than as constants beside the drawing, because a second font will not have
/// the same ones: a 12x12 CJK font fits thirteen characters a line where this one fits twenty-six, and the layout has
/// to ask rather than assume.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Font {
    /// What this font is called: the name in its file, or the file's own name; `panel-6x8` for the one built in.
    pub name: String,
    /// How many pixels the cursor moves after a character.
    pub advance: usize,
    /// How many pixels apart lines are placed.
    pub height: usize,
    /// Rows of ink a glyph of this font may use.
    pub rows: usize,
    /// What this font draws for a character it has no glyph for - the box that says something was here.
    pub box_glyph: [u8; 8],
    /// The glyphs this font draws, keyed by the folded character: eight bytes each, one per column, bit
    /// `row` of a byte being that pixel.
    glyphs: std::collections::BTreeMap<char, [u8; 8]>,
}

/// The box this project draws for a character no font has.
pub const BOX: [u8; 8] = [0xfe, 0x82, 0x82, 0x82, 0x82, 0xfe, 0x00, 0x00];

impl Font {
    /// A font made of what it has: the metrics, and one glyph per character.
    pub fn new(
        name: impl Into<String>,
        advance: usize,
        height: usize,
        rows: usize,
        glyphs: std::collections::BTreeMap<char, [u8; 8]>,
    ) -> Self {
        Self {
            name: name.into(),
            advance,
            height,
            rows,
            box_glyph: BOX,
            glyphs,
        }
    }

    /// The ink for one character, or the box for one this font does not have.
    pub fn glyph(&self, character: char) -> [u8; 8] {
        self.known(character).unwrap_or(self.box_glyph)
    }

    /// How many glyphs this font carries. A count is worth being able to ask for: it is how a font file that lost
    /// half its table on the way in gets noticed.
    pub fn glyph_count(&self) -> usize {
        self.glyphs.len()
    }

    /// The ink for a character, if this font has one at all.
    pub fn known(&self, character: char) -> Option<[u8; 8]> {
        self.glyphs.get(&drawable(character)).copied()
    }
}

/// The font this panel has always drawn with: 128 ASCII glyphs, 56 Greek, 130 Cyrillic.
///
/// Built once from the three tables, which are still the source of truth for the built-in glyphs.
pub fn panel() -> &'static Font {
    static PANEL: std::sync::OnceLock<Font> = std::sync::OnceLock::new();
    PANEL.get_or_init(|| {
        let mut glyphs = std::collections::BTreeMap::new();
        for code in 0..128u32 {
            if let Some(character) = char::from_u32(code) {
                glyphs.insert(character, GLYPHS[code as usize]);
            }
        }
        for (character, ink) in GREEK.iter().chain(CYRILLIC.iter()) {
            glyphs.insert(*character, *ink);
        }
        Font::new("panel-6x8", ADVANCE, LINE_HEIGHT, GLYPH_ROWS, glyphs)
    })
}

/// The first font in the stack that has a glyph for this character, drawn by *that* font.
///
/// **This is what makes one string able to hold several scripts.** A font stack is what a browser and a terminal do
/// with the same problem, and it needs nothing of the bidirectional algorithm unless the scripts run in opposite
/// directions - so Latin, Greek, Cyrillic, runes and CJK can share a line today. A character no font has falls to the
/// first font in the stack, which draws its box rather than dropping it.
pub fn in_stack(fonts: &[Font], character: char) -> (&Font, [u8; 8], bool) {
    for font in fonts {
        if let Some(ink) = font.known(character) {
            return (font, ink, true);
        }
    }
    match fonts.first() {
        Some(font) => (font, font.box_glyph, false),
        None => {
            let panel = panel();
            (panel, panel.box_glyph, false)
        }
    }
}

/// The character as this font can draw it.
///
/// The font is 128 glyphs of ASCII and the text comes from outside it: a browser puts U+2019 in a video's title -
/// *"EVERYONE’S Car!"*, which is exactly what put a box on the pad - and no ASCII font has a glyph for it. These are
/// the characters that actually turn up in titles and readings, folded to the shape the font does have. Anything
/// else stays a box, which at least says something was there.
fn drawable(character: char) -> char {
    match character {
        // apostrophes, much the commonest: browsers and phones write the typographic one
        '\u{2019}' | '\u{2018}' | '\u{201b}' | '\u{00b4}' | '\u{2032}' => '\'',
        '\u{201c}' | '\u{201d}' | '\u{201e}' | '\u{2033}' => '"',
        // dashes, then the things a sensor or a title drops in
        '\u{2013}' | '\u{2014}' | '\u{2015}' | '\u{2212}' => '-',
        '\u{2026}' => '.',
        '\u{2022}' | '\u{00b7}' | '\u{2219}' => '*',
        '\u{00a0}' | '\u{2009}' | '\u{200a}' => ' ',
        '\u{00d7}' => 'x',
        '\u{00e9}' | '\u{00e8}' | '\u{00ea}' | '\u{00eb}' => 'e',
        _ => character,
    }
}

/// The eight column bytes for a character in this project's own font, or a box for one it does not have.
pub fn glyph(character: char) -> [u8; 8] {
    panel().glyph(character)
}

/// How far the cursor moves after a character.
///
/// Six, not eight: the glyphs carry their ink in the left five or six columns, and the applets are laid out
/// for this. The longest line among the existing applets is 25 characters, which fits 26 times over at six
/// and overflows the panel at eight.
pub const ADVANCE: usize = 6;
/// Columns of ink a glyph may use.
pub const GLYPH_COLUMNS: usize = 6;
/// Rows of ink a glyph may use.
pub const GLYPH_ROWS: usize = 8;
/// How far apart lines of text are placed, in pixels.
pub const LINE_HEIGHT: usize = 8;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_shapes_survived_the_transpose() {
        // 'A' is solid down its left column, and its top-left pixel is empty
        let a = glyph('A');
        assert!(a[0] != 0, "the left column of A is empty: {a:?}");
        assert_eq!(a[0] & 1, 0, "the top-left pixel of A should be empty");
        // space is blank, so text over a picture leaves the picture's blank pixels blank
        assert_eq!(glyph(' '), [0; 8]);
        // A character outside the table is not silently blank - but the box has to fit its own cell. It used to be
        // eight columns of ink against an advance of six, which drew over the two characters beside it; the title
        // "EVERYONE’S Car!" is what showed it.
        assert_eq!(
            glyph('\u{2500}'),
            [0xfe, 0x82, 0x82, 0x82, 0x82, 0xfe, 0x00, 0x00]
        );
    }

    #[test]
    fn the_table_is_the_whole_ascii_range() {
        assert_eq!(GLYPHS.len(), 128);
        assert_eq!(glyph(' '), [0; 8]);
        assert_ne!(glyph('!'), [0; 8], "an exclamation mark is not blank");
    }
}

#[cfg(test)]
mod what_the_font_can_actually_draw {
    use super::*;

    #[test]
    fn every_glyph_fits_its_own_cell_before_the_cursor_moves() {
        // The box an unknown character drew was eight columns of ink against an advance of six, which is why it
        // overlapped the characters either side of it. Nothing may draw past the advance.
        for code in 0..128u32 {
            let ink = GLYPHS[code as usize];
            assert!(
                ink[ADVANCE..].iter().all(|byte| *byte == 0),
                "glyph {code} draws into the next character's cell: {ink:?}"
            );
        }
        let unknown = glyph('\u{4e2d}');
        assert!(
            unknown[ADVANCE..].iter().all(|byte| *byte == 0),
            "the box for an unknown character eats its neighbours: {unknown:?}"
        );
    }

    #[test]
    fn the_characters_that_turn_up_in_titles_are_drawn_rather_than_boxed() {
        // A title exactly as the player reports it: a typographic apostrophe, and a box on the pad before this.
        for (from, to) in [
            ('\u{2019}', '\''),
            ('\u{2018}', '\''),
            ('\u{201c}', '"'),
            ('\u{201d}', '"'),
            ('\u{2013}', '-'),
            ('\u{2014}', '-'),
            ('\u{2026}', '.'),
            ('\u{2022}', '*'),
            ('\u{00a0}', ' '),
        ] {
            assert_eq!(
                glyph(from),
                glyph(to),
                "{} is still a box where {} would be drawn",
                from.escape_unicode(),
                to
            );
        }
        // and a character with no relation to any of them still says something was there
        assert_ne!(glyph('\u{4e2d}'), glyph('?'));
    }
}

#[cfg(test)]
mod the_greek_glyphs {
    use super::*;

    #[test]
    fn they_fit_their_cells_and_the_shapes_survived_the_transpose() {
        assert_eq!(GREEK.len(), 56, "the Greek table lost glyphs");
        // the same invariant the ASCII table is held to: nothing draws past the advance
        for (character, ink) in GREEK {
            assert!(
                ink[ADVANCE..].iter().all(|byte| *byte == 0),
                "{} draws into the next character's cell: {ink:?}",
                character.escape_unicode()
            );
        }
        // and the shapes are the ones a reader would recognise, checked against the art rather than the source's
        // bytes: Alpha is the same figure as a Latin A, Theta is round, Pi is a bar on two legs.
        assert_eq!(glyph('\u{0391}'), glyph('A'), "Alpha is not the shape of A");
        let theta = glyph('\u{0398}');
        assert_ne!(theta[0], 0, "Theta lost its top: {theta:?}");
        assert_eq!(
            theta[0] & 1,
            0,
            "Theta's top-left pixel should be empty, as a circle's is"
        );
        let pi = glyph('\u{03a0}');
        assert_ne!(pi[0], pi[1], "Pi's bar and its legs are the same shape");
        // a Greek letter the table does not carry is still a box, not silence
        assert_eq!(
            glyph('\u{03d7}'),
            [0xfe, 0x82, 0x82, 0x82, 0x82, 0xfe, 0x00, 0x00]
        );
    }
}

#[cfg(test)]
mod the_cyrillic_glyphs {
    use super::*;

    #[test]
    fn they_fit_their_cells_and_the_shapes_survived_the_conversion() {
        assert_eq!(CYRILLIC.len(), 130, "the Cyrillic table lost glyphs");
        // the same invariant as the other two tables: nothing may draw past the advance. Twenty-six other glyphs
        // were dropped by hand when the table was taken from the source for exactly this reason.
        for (character, ink) in CYRILLIC {
            assert!(
                ink[ADVANCE..].iter().all(|byte| *byte == 0),
                "{} draws into the next character's cell: {ink:?}",
                character.escape_unicode()
            );
        }
        // The shapes are the ones the source draws, checked by reading them rather than assuming they match Latin.
        // Cyrillic А and Latin A are *not* the same figure: the source draws the Cyrillic one with its crossbar low
        // and the Latin one as a triangle, which is right - an assertion that they matched was mine, and wrong.
        assert_ne!(glyph('\u{0410}'), [0; 8], "Cyrillic А came out blank");
        assert_eq!(
            glyph('\u{0410}')[4],
            glyph('\u{0410}')[0],
            "Cyrillic А lost its crossbar"
        );
        assert_ne!(glyph('\u{042f}'), glyph('\u{0410}'), "Я came out as А");
        assert_ne!(glyph('\u{0416}'), [0; 8], "Ж came out blank");
        // and a Cyrillic letter the table does not carry is still a box
        assert_eq!(
            glyph('\u{0460}'),
            [0xfe, 0x82, 0x82, 0x82, 0x82, 0xfe, 0x00, 0x00]
        );
    }
}

#[cfg(test)]
mod a_string_can_hold_more_than_one_script {
    use super::*;
    use crate::Frame;

    /// A stand-in for a wider font: it knows one character, and moves the pen twice as far.
    fn wide() -> Font {
        Font::new(
            "test-wide",
            12,
            12,
            6,
            [('W', [0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x00, 0x00])]
                .into_iter()
                .collect(),
        )
    }

    /// A stand-in for a taller font, which is what a CJK font is on this panel.
    fn tall() -> Font {
        Font::new(
            "test-tall",
            12,
            12,
            7,
            [('T', [0xff; 8])].into_iter().collect(),
        )
    }

    #[test]
    fn a_line_takes_the_height_of_the_tallest_font_it_actually_used() {
        // the line grows rather than the glyph being clipped. Text that uses only the panel font is
        // unchanged, which is what keeps every existing screen exactly as it was.
        // the stand-in comes first, as a CJK font would: the panel font knows every ASCII letter, so a stack the
        // other way round never reaches the second font - which is how this test was wrong the first time
        let stack = [tall(), panel().clone()];
        assert_eq!(
            Frame::line_height_in(&[panel().clone()], "hello"),
            panel().height
        );
        assert_eq!(
            Frame::line_height_in(&stack, "hello"),
            panel().height,
            "a line with no tall character in it grew anyway"
        );
        assert_eq!(
            Frame::line_height_in(&stack, "heTlo"),
            tall().height,
            "a line with a tall character did not grow"
        );
        // and the frame answers the same question about the fonts it is carrying
        let frame = Frame::new().with_fonts(vec![tall(), panel().clone()]);
        assert_eq!(frame.line_height("heTlo"), tall().height);
        assert_eq!(frame.line_height("hello"), panel().height);
    }

    #[test]
    fn each_character_is_drawn_and_measured_by_the_font_that_has_it() {
        // the wide font first, standing in for a CJK font: it takes the characters it knows and the panel font takes
        // everything else, which is what a stack is for
        let stack = [wide(), panel().clone()];
        let (font, ink, found) = in_stack(&stack, 'W');
        assert_eq!(font.name, "test-wide", "the first font did not take W");
        assert!(found && ink[0] == 0xff);
        let (font, _, found) = in_stack(&stack, 'A');
        assert_eq!(
            font.name,
            panel().name,
            "a character the first font lacks did not fall through"
        );
        assert!(found);

        // and the advance follows the font that drew, which is the whole point: twelve for W, six for A
        let mut frame = Frame::new();
        let width = frame.text_in(&stack, 0, 0, "AW");
        assert_eq!(
            width,
            panel().advance + wide().advance,
            "the line was not measured per glyph"
        );
        // the W's block starts after the A and is twelve wide, so it reaches column 17
        assert!(
            frame.get(6, 0),
            "the wide glyph did not start where the A ended"
        );
        // The pen moves twelve for the W although its ink is six columns wide, which is what a font with spacing is.
        // The proof is that nothing follows until column eighteen.
        assert!(
            (12..18).all(|column| !frame.get(column, 0)),
            "the wide glyph's advance is not being honoured"
        );
        assert_eq!(
            frame.text_in(&stack, 0, 0, "AW"),
            18,
            "the line is six for the A and twelve for the W, so it was not measured per glyph"
        );

        // a character no font has falls to the first font, which draws its box rather than dropping it
        let (font, ink, found) = in_stack(&stack, '\u{4e2d}');
        assert!(!found);
        assert_eq!(
            font.name, "test-wide",
            "an unknown character should fall to the first font in the stack"
        );
        assert_eq!(ink, [0xfe, 0x82, 0x82, 0x82, 0x82, 0xfe, 0x00, 0x00]);

        // and an ordinary line through the same path is unchanged from what `text` drew before
        let mut one = Frame::new();
        let mut two = Frame::new();
        one.text(0, 0, "A\u{0416}Z");
        two.text_in(&[panel().clone()], 0, 0, "A\u{0416}Z");
        assert!(one.is_blank(0, 0, 200, 43) == two.is_blank(0, 0, 200, 43));
        for row in 0..8 {
            for column in 0..20 {
                assert_eq!(one.get(column, row), two.get(column, row));
            }
        }
    }
}

#[cfg(test)]
mod the_row_the_descenders_live_in {
    use super::*;
    use crate::Frame;

    #[test]
    fn the_eighth_row_of_a_glyph_is_drawn() {
        // The bottom of some Cyrillic letters was cut off. The glyphs carry a descender in their eighth
        // row - Д's feet, ц's and щ's tails - and nothing was drawing it, because the panel font declared seven rows.
        assert_eq!(panel().rows, GLYPH_ROWS);
        assert_eq!(GLYPH_ROWS, 8, "a glyph may use the whole eight-row cell");
        let mut frame = Frame::new();
        frame.text(0, 0, "\u{0414}");
        assert!(
            (0..6).any(|column| frame.get(column, 7)),
            "the eighth row of Д was not drawn, so its feet are missing"
        );
        // and a Latin descender in the same cell still sits where it did: this font's own letters are seven rows
        let mut latin = Frame::new();
        latin.text(0, 0, "g");
        assert!(
            (0..8).any(|row| (0..6).any(|column| latin.get(column, row))),
            "g vanished"
        );
    }
}
